class Animal {
    protected String name;
    public Animal(String name) { this.name = name; }

    // Protected in superclass
    protected void makeSound() {
        System.out.println(name + " makes a generic animal sound");
    }
}

class Dog extends Animal {
    public Dog(String name) { super(name); }

    // Overriding: Widens access from protected to public (Legal!)
    public void makeSound() {
        System.out.println(name + " barks: Woof! Woof!");
    }
}

class Cat extends Animal {
    public Cat(String name) { super(name); }

    // Overriding: Matches protected access (Legal!)
    protected void makeSound() {
        System.out.println(name + " meows: Purr... Meow!");
    }
}

public class OverridingRulesDemo {
    public static void main(String[] args) {
        Animal a1 = new Dog("Buddy");
        Animal a2 = new Cat("Luna");

        a1.makeSound(); // Invokes Dog.makeSound()
        a2.makeSound(); // Invokes Cat.makeSound()
    }
}

