class BankAccount {
    public double calculateInterest(double balance) {
        return balance * 0.02;
    }
}

class HighYieldSavingsAccount extends BankAccount {
    public double calculateInterest(double balance) {
        return balance * 0.05;
    }
}

public class Main {
    public static void main(String[] args) {
        BankAccount b1 = new BankAccount();
        BankAccount b2 = new HighYieldSavingsAccount();
        System.out.println("Standard Interest: $" + b1.calculateInterest(1000.0));
        System.out.println("High-Yield Interest: $" + b2.calculateInterest(1000.0));
    }
}

class ShippingCalculator {
    public double computeFee(double weightKg) {
        return weightKg * 5.0;
    }
}

class ExpressShipping extends ShippingCalculator {
    public double computeFee(double weightKg) {
        return (weightKg * 8.0) + 15.0;
    }
}

class InternationalShipping extends ShippingCalculator {
    public double computeFee(double weightKg) {
        return (weightKg * 12.0) + 35.0;
    }
}

public class Main {
    public static void main(String[] args) {
        ShippingCalculator s1 = new ShippingCalculator();
        ShippingCalculator s2 = new ExpressShipping();
        ShippingCalculator s3 = new InternationalShipping();
        System.out.println("Standard Shipping: $" + s1.computeFee(10.0));
        System.out.println("Express Shipping: $" + s2.computeFee(10.0));
        System.out.println("International Shipping: $" + s3.computeFee(10.0));
    }
}

