class Loan {
    protected double principal;
    protected double annualRate;
    protected int tenureYears;

    public Loan(double principal, double annualRate, int tenureYears) {
        this.principal = principal;
        this.annualRate = annualRate;
        this.tenureYears = tenureYears;
    }

    public double calculateMonthlyPayment() {
        double monthlyRate = (annualRate / 100.0) / 12.0;
        int months = tenureYears * 12;
        return (principal * monthlyRate) / (1 - Math.pow(1 + monthlyRate, -months));
    }
}

class PersonalLoan extends Loan {
    public PersonalLoan(double principal, double annualRate, int tenureYears) {
        super(principal, annualRate, tenureYears);
    }
    public double calculateMonthlyPayment() {
        double base = super.calculateMonthlyPayment();
        return Math.round((base + 15.0) * 100.0) / 100.0; // $15 maintenance
    }
}

class MortgageLoan extends Loan {
    public MortgageLoan(double principal, double annualRate, int tenureYears) {
        super(principal, annualRate, tenureYears);
    }
    public double calculateMonthlyPayment() {
        double base = super.calculateMonthlyPayment();
        return Math.round((base + 350.0) * 100.0) / 100.0; // $350 escrow
    }
}

public class Main {
    public static void main(String[] args) {
        Loan pLoan = new PersonalLoan(20000.0, 11.5, 5);
        Loan mLoan = new MortgageLoan(300000.0, 6.0, 30);
        System.out.println("Personal Loan Monthly: $" + pLoan.calculateMonthlyPayment());
        System.out.println("Mortgage Monthly: $" + mLoan.calculateMonthlyPayment() + " (Escrow Included)");
    }
}
